export function memoryReconsolidation(memoryStore) {
  const replayedMemories = memoryStore.replay();
  const prunedMemories = pruneLowValueEmbeddings(replayedMemories);
  memoryStore.update(prunedMemories);
}

function pruneLowValueEmbeddings(memories) {
  return memories.filter(memory => memory.value > 0.5);
}